'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var ai = require( './../lib/ai.js' );


// FIXTURES //

var smallPositive = require( './fixtures/c/cephes/small_positive.json' );
var smallNegative = require( './fixtures/c/cephes/small_negative.json' );
var largePositive = require( './fixtures/c/cephes/large_positive.json' );
var largeNegative = require( './fixtures/c/cephes/large_negative.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof ai, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function evaluates the Airy function Ai(x) (large negative values)', function test( t ) {
	var expectedAi;
	var delta;
	var out;
	var tol;
	var x;
	var i;

	expectedAi = largeNegative.Ai;
	x = largeNegative.x;
	for ( i = 0; i < x.length; i++ ) {
		out = ai( x[i] );
		if ( out === expectedAi[i] ) {
			t.strictEqual( out, expectedAi[i], 'x: '+x[i]+', Ai: '+out+', expected: '+expectedAi[i] );
		} else {
			delta = abs( out - expectedAi[i] );
			tol = 3.0 * EPS * abs( expectedAi[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x[i]+'. Ai: '+out+'. E: '+expectedAi[i]+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
	}
	t.end();
});

tape( 'the function evaluates the Airy function Ai(x) (large negative positive values)', function test( t ) {
	var expectedAi;
	var relTol;
	var absTol;
	var delta;
	var out;
	var x;
	var i;

	expectedAi = largePositive.Ai;
	x = largePositive.x;
	for ( i = 0; i < x.length; i++ ) {
		out = ai( x[i] );
		if ( out === expectedAi[i] ) {
			t.strictEqual( out, expectedAi[i], 'x: '+x[i]+', Ai: '+out+', expected: '+expectedAi[i] );
		} else {
			delta = abs( out - expectedAi[i] );
			relTol = EPS * abs( expectedAi[i] );
			absTol = 1e-8 * EPS;
			t.strictEqual( delta <= relTol || delta <= absTol, true, 'within tolerance. x: '+x[i]+'. Ai: '+out+'. E: '+expectedAi[i]+'. Δ: '+delta+'. relTol: '+relTol+'. absTol: '+absTol+'.' );
		}
	}
	t.end();
});

